feature-integer-summary:
def summarize_values(values):
    """Return count, minimum, maximum, and mean in one pass."""
    count = 0
    total = 0
    minimum = None
    maximum = None
    for value in values:
        count += 1
        total += value
        minimum = value if minimum is None or value < minimum else minimum
        maximum = value if maximum is None or value > maximum else maximum
    if count == 0:
        return {"count": 0, "min": None, "max": None, "mean": None}
    return {"count": count, "min": minimum, "max": maximum, "mean": total / count}

maintenance-safe-mean:
def mean(values):
    """Return the arithmetic mean of a non-empty numeric iterable."""
    count = 0
    total = 0
    for value in values:
        count += 1
        total += value
    if count == 0:
        raise ValueError("mean is undefined for empty input")
    return total / count
